// @ts-check
// Deep-module enforcement for dependency-cruiser.
//
// Each package under the packages root is a DEEP MODULE: a lot of behaviour
// behind a small interface. A package's PUBLIC SURFACE is its ENTRY POINTS:
// the files at the package root. Implementation lives in SUBFOLDERS and is
// private (by convention `lib/` for implementation and `tests/` for tests,
// though any subfolder is private). A package may expose several small entry
// points (index.ts, client.ts, server.ts, …); prefer that over one giant
// barrel index.
//
// The only thing you should ever need to edit here is PACKAGES_ROOT.

/** Where packages live. One immediate child dir per package (flat, no nesting). */
const PACKAGES_ROOT = "src/packages";

// --- derived patterns (no need to edit) -------------------------------------
const R = PACKAGES_ROOT;
/**
 * A package's private internals: anything nested inside a package subfolder.
 * The package's root files are its entry points and are NOT matched here:
 * they stay importable from outside.
 */
const PACKAGE_INTERNALS = `^${R}/[^/]+/[^/]+/`;

/** @type {import('dependency-cruiser').IConfiguration} */
module.exports = {
  forbidden: [
    {
      name: "entrypoint-boundary-from-app",
      comment:
        "App/root code may import a package's entry points (its root files), but nothing inside its subfolders.",
      severity: "error",
      from: { pathNot: `^${R}/` }, // importer is NOT inside any package
      to: { path: PACKAGE_INTERNALS },
    },
    {
      name: "entrypoint-boundary-across-packages",
      comment:
        "A package's own files import each other freely, but may reach OTHER packages only through their entry points, never their internals.",
      severity: "error",
      // importer is inside a package ($1), but is not a test file
      from: { path: `^${R}/([^/]+)/`, pathNot: `^${R}/[^/]+/tests/` },
      to: {
        path: PACKAGE_INTERNALS,
        pathNot: `^${R}/$1/`, // same package → intra-package freedom
      },
    },
    {
      name: "tests-through-entrypoints",
      comment:
        "A package's tests exercise it through its entry points like everyone else: they may import any package's entry points and their own tests/ fixtures, but never any package's internals, not even their own.",
      severity: "error",
      from: { path: `^${R}/([^/]+)/tests/` }, // a test file, in package $1
      to: {
        path: PACKAGE_INTERNALS,
        pathNot: `^${R}/$1/tests/`, // own tests/ fixtures → allowed
      },
    },
    {
      name: "tests-folder-is-private",
      comment:
        "A package's tests/ folder is reachable only from tests: nothing else may import fixtures.",
      severity: "error",
      from: { pathNot: `^${R}/[^/]+/tests/` }, // importer is not itself a test
      to: { path: `^${R}/[^/]+/tests/` },
    },
    {
      name: "no-circular",
      comment: "No dependency cycles. Scope to `^${R}/` if you want to allow cycles outside packages.",
      severity: "error",
      from: {},
      to: { circular: true },
    },

    // --- Layering (optional, off by default) ----------------------------------
    // Interface-hiding controls HOW you import (through the entry points).
    // Layering controls WHICH packages may depend on which. Add your own rules
    // here, e.g.:
    //
    // {
    //   name: "ui-may-not-depend-on-billing",
    //   severity: "error",
    //   from: { path: `^${R}/ui/` },
    //   to:   { path: `^${R}/billing/` },
    // },
  ],
  options: {
    doNotFollow: { path: "node_modules" },
    tsConfig: { fileName: "tsconfig.json" },
    enhancedResolveOptions: {
      extensions: [".ts", ".tsx", ".js", ".jsx", ".json"],
    },
  },
};

import { randomUUID } from "node:crypto";
import { expect, it } from "@effect/vitest";
import { ConfigProvider, Deferred, Effect, Fiber } from "effect";
import { Client } from "pg";
import { PostgresProbeLive } from "../src/adapters/postgres.ts";
import { PersistenceProbe } from "../src/capabilities/persistence-probe/contract.ts";

const databaseUrl = process.env.HERO_TEST_DATABASE_URL;
if (!databaseUrl) {
  throw new Error(
    "HERO_TEST_DATABASE_URL must point to a disposable PostgreSQL database; see docs/postgres-validation.md",
  );
}
it.effect("round trips an integer through PostgreSQL and Drizzle", () =>
  Effect.gen(function* () {
    const probe = yield* PersistenceProbe;
    expect(yield* probe.roundTrip(42)).toBe(42);
  }).pipe(
    Effect.provide(PostgresProbeLive),
    Effect.provide(
      ConfigProvider.layer(
        ConfigProvider.fromUnknown({ DATABASE_URL: databaseUrl }),
      ),
    ),
  ),
);

it.effect("translates a rejected integer query and keeps the pool usable", () =>
  Effect.gen(function* () {
    const probe = yield* PersistenceProbe;
    const failure = yield* probe.roundTrip(Number.NaN).pipe(Effect.flip);
    expect(failure).toMatchObject({
      _tag: "PersistenceUnavailable",
      operation: "query",
    });
    expect(JSON.stringify(failure)).not.toContain("NaN");
    expect(yield* probe.roundTrip(-7)).toBe(-7);
  }).pipe(
    Effect.provide(PostgresProbeLive),
    Effect.provide(
      ConfigProvider.layer(
        ConfigProvider.fromUnknown({ DATABASE_URL: databaseUrl }),
      ),
    ),
  ),
);

it.effect("reports connection failure while constructing the Layer", () => {
  const missingDatabase = new URL(databaseUrl);
  missingDatabase.pathname = "/hero_missing_database_18";
  return PersistenceProbe.pipe(
    Effect.provide(PostgresProbeLive),
    Effect.provide(
      ConfigProvider.layer(
        ConfigProvider.fromUnknown({ DATABASE_URL: missingDatabase.href }),
      ),
    ),
    Effect.flip,
    Effect.map((failure) => {
      expect(failure).toMatchObject({
        _tag: "PersistenceUnavailable",
        operation: "connect",
      });
      expect(JSON.stringify(failure)).not.toContain("hero_missing_database_18");
      return failure;
    }),
  );
});

it.effect.each([
  {},
  { DATABASE_URL: "" },
  { DATABASE_URL: "secret-invalid-url" },
  { DATABASE_URL: "https://secret.example/db" },
])("rejects invalid configuration without exposing its value: %j", (settings) =>
  PersistenceProbe.pipe(
    Effect.provide(PostgresProbeLive),
    Effect.provide(ConfigProvider.layer(ConfigProvider.fromUnknown(settings))),
    Effect.flip,
    Effect.map((failure) => {
      expect(failure).toMatchObject({
        _tag: "PersistenceUnavailable",
        operation: "configuration",
      });
      expect(JSON.stringify(failure)).not.toContain("secret");
      return failure;
    }),
  ),
);

const observeSessions = Effect.acquireRelease(
  Effect.promise(async () => {
    const client = new Client({ connectionString: databaseUrl });
    await client.connect();
    return client;
  }),
  (client) => Effect.promise(() => client.end()),
);

async function sessionCounts(observer: Client, name: string) {
  const result = await observer.query<{ count: number }>(
    "select count(*)::int as count from pg_stat_activity where application_name = $1",
    [name],
  );
  return result.rows;
}

it.effect.each([false, true])(
  "releases PostgreSQL sessions after scope exit (query failure: %s)",
  (fail) =>
    Effect.scoped(
      Effect.gen(function* () {
        const observer = yield* observeSessions;
        const name = randomUUID();
        const url = new URL(databaseUrl);
        url.searchParams.set("application_name", name);
        const operation = Effect.gen(function* () {
          const probe = yield* PersistenceProbe;
          const sessions = yield* Effect.promise(() =>
            sessionCounts(observer, name),
          );
          expect(sessions).toEqual([{ count: 1 }]);
          yield* probe.roundTrip(fail ? Number.NaN : 42);
        }).pipe(
          Effect.provide(PostgresProbeLive),
          Effect.provide(
            ConfigProvider.layer(
              ConfigProvider.fromUnknown({ DATABASE_URL: url.href }),
            ),
          ),
          Effect.exit,
        );
        const outcome = yield* operation;
        expect(outcome._tag).toBe(fail ? "Failure" : "Success");
        yield* Effect.promise(async () => {
          await expect
            .poll(() => sessionCounts(observer, name))
            .toEqual([{ count: 0 }]);
        });
      }),
    ),
);

it.effect("interruption awaits pool cleanup before the fiber exits", () =>
  Effect.scoped(
    Effect.gen(function* () {
      const observer = yield* observeSessions;
      const started = yield* Deferred.make<void>();
      const name = randomUUID();
      const url = new URL(databaseUrl);
      url.searchParams.set("application_name", name);
      const fiber = yield* Effect.gen(function* () {
        const probe = yield* PersistenceProbe;
        expect(yield* probe.roundTrip(18)).toBe(18);
        yield* Deferred.succeed(started, undefined);
        yield* Effect.never;
      }).pipe(
        Effect.provide(PostgresProbeLive),
        Effect.provide(
          ConfigProvider.layer(
            ConfigProvider.fromUnknown({ DATABASE_URL: url.href }),
          ),
        ),
        Effect.forkChild,
      );
      yield* Deferred.await(started);
      yield* Fiber.interrupt(fiber);
      yield* Effect.promise(async () => {
        await expect
          .poll(() => sessionCounts(observer, name))
          .toEqual([{ count: 0 }]);
      });
    }),
  ),
);

it.effect("survives PostgreSQL closing an idle pooled session", () =>
  Effect.scoped(
    Effect.gen(function* () {
      const observer = yield* observeSessions;
      const name = randomUUID();
      const url = new URL(databaseUrl);
      url.searchParams.set("application_name", name);
      yield* Effect.gen(function* () {
        const probe = yield* PersistenceProbe;
        yield* Effect.promise(() =>
          observer.query(
            "select pg_terminate_backend(pid) from pg_stat_activity where application_name = $1",
            [name],
          ),
        );
        // Wait for the server to acknowledge termination before requesting a replacement.
        yield* Effect.promise(async () => {
          await expect
            .poll(() => sessionCounts(observer, name))
            .toEqual([{ count: 0 }]);
        });
        expect(yield* probe.roundTrip(21)).toBe(21);
      }).pipe(
        Effect.provide(PostgresProbeLive),
        Effect.provide(
          ConfigProvider.layer(
            ConfigProvider.fromUnknown({ DATABASE_URL: url.href }),
          ),
        ),
      );
    }),
  ),
);
